'use strict';
let KEY='zen-kanban-v1';const COLORS=['#7950c8','#d66b9e','#eb8b50','#9b79cf','#b85a91','#bf7953'],COLS=['Idea','List','Doing','Done'];
const $=s=>document.querySelector(s),uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2,12)}`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tint=c=>c+'18',today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}),dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'}):'Không thời hạn';
function sample(){const make=(title,col,n,k,tag='Thiết kế')=>({id:uid(),title,col,description:'Dữ liệu minh họa — bạn có thể chỉnh sửa hoặc xóa để bắt đầu công việc của mình.',tag,due:'',checks:Array.from({length:n},(_,i)=>({id:uid(),text:['Phác thảo ý tưởng','Hoàn thiện nội dung','Kiểm tra và chỉnh sửa','Sẵn sàng xuất bản'][i%4],done:i<k}))});return {schema:1,demo:true,projects:[{id:uid(),name:'Hương Thiền Nature',description:'Nuôi dưỡng một hệ sinh thái sống an lành, gần gũi thiên nhiên.',color:COLORS[0],icon:'✺',columns:[...COLS],tasks:[make('Lên ý tưởng cho mùa retreat mới','Idea',3,0,'Ý tưởng'),make('Biên tập câu chuyện thương hiệu','List',3,1,'Nội dung'),make('Thiết kế trang Retreat & Thiền','Doing',4,2),make('Hoàn thiện bộ nhận diện','Done',3,3),make('Xây dựng thư viện hình ảnh','Done',2,2)]},{id:uid(),name:'Zen Studio',description:'Không gian sáng tạo nội dung, để mỗi câu chuyện được cất lời.',color:COLORS[1],icon:'✎',columns:[...COLS],tasks:[make('Phác thảo trình biên tập mới','Idea',2,0),make('Tinh chỉnh giao diện dashboard','Doing',4,2),make('Thiết kế màn hình đăng nhập','Done',3,3),make('Chuẩn bị tài liệu hướng dẫn','List',3,0,'Tài liệu')]},{id:uid(),name:'Sổ nợ An Tâm',description:'Từng bước chủ động tài chính, nhẹ lòng hơn mỗi ngày.',color:COLORS[2],icon:'◈',columns:[...COLS],tasks:[make('Tối ưu thanh tiến độ','Doing',3,2),make('Kiểm tra giao diện điện thoại','List',3,0,'Kiểm thử'),make('Hoàn thiện nhận diện ứng dụng','Done',2,2)]},{id:uid(),name:'Farm Yêu Thương',description:'Gieo những điều tử tế, kể những câu chuyện từ khu vườn.',color:COLORS[3],icon:'❀',columns:[...COLS],tasks:[make('Lên lịch kể chuyện khu vườn','Idea',2,0,'Nội dung'),make('Chọn ảnh cho câu chuyện mới','Doing',3,1,'Hình ảnh'),make('Thiết kế trang chủ nông trại','Done',3,3)]}]};}
function valid(data){if(!data||data.schema!==1||!Array.isArray(data.projects)||data.projects.length>100)return false;const ids=new Set();const id=x=>typeof x==='string'&&x.length<100&&!ids.has(x)&&!!ids.add(x),str=(x,n)=>typeof x==='string'&&x.length<=n;return data.projects.every(p=>id(p.id)&&str(p.name,100)&&p.name.trim()&&str(p.description,2000)&&/^#[\da-f]{6}$/i.test(p.color)&&str(p.icon,8)&&Array.isArray(p.columns)&&p.columns.length>=4&&p.columns.length<=20&&COLS.every(c=>p.columns.includes(c))&&new Set(p.columns).size===p.columns.length&&p.columns.every(c=>str(c,40)&&c.trim())&&Array.isArray(p.tasks)&&p.tasks.length<=2000&&p.tasks.every(t=>id(t.id)&&str(t.title,200)&&t.title.trim()&&str(t.description,5000)&&str(t.tag,40)&&(!t.labels||(Array.isArray(t.labels)&&t.labels.length<=20&&t.labels.every(l=>l&&str(l.name,40)&&/^#[a-f0-9]{6}$/i.test(l.color))))&&str(t.due,10)&&(!t.due||/^\d{4}-\d{2}-\d{2}$/.test(t.due))&&p.columns.includes(t.col)&&Array.isArray(t.checks)&&t.checks.length<=200&&t.checks.every(c=>id(c.id)&&str(c.text,300)&&typeof c.done==='boolean')&&(t.col!=='Done'||t.checks.every(c=>c.done))));}
let data;try{const raw=localStorage.getItem(KEY);data=raw?JSON.parse(raw):sample();if(!valid(data))throw Error('Dữ liệu lưu không hợp lệ');}catch(e){data={schema:1,projects:[]};setTimeout(()=>notify('Không đọc được dữ liệu cũ. Hãy nhập bản sao lưu; dữ liệu cũ chưa bị ghi đè.'),500);}
let view='dashboard',active=null,query='',filterProject='',filterStatus='',drag=null,editing=null,undoData=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));$('#save-state').textContent='● Đã lưu trên máy';return true;}catch(e){$('#save-state').textContent='⚠ Chưa lưu được';notify('Bộ nhớ trình duyệt không khả dụng hoặc đã đầy. Hãy xuất bản sao JSON ngay.');return false;}}
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function units(t){return {total:1+t.checks.length,done:(t.col==='Done'?1:0)+t.checks.filter(c=>c.done).length};}
function progress(tasks){const sums=tasks.reduce((a,t)=>{const u=units(t);return {total:a.total+u.total,done:a.done+u.done};},{total:0,done:0});return {...sums,pct:sums.total?Math.round(sums.done/sums.total*100):0};}
function taskPct(t){return t.checks.length?Math.round(t.checks.filter(c=>c.done).length/t.checks.length*100):t.col==='Done'?100:0;}
function allTasks(){return data.projects.flatMap(p=>p.tasks.map(t=>({...t,project:p})));}
function project(id=active){return data.projects.find(p=>p.id===id);}
function found(t){return (t.title+' '+t.description+' '+t.tag+' '+(t.labels||[]).map(l=>l.name).join(' ')+' '+(t.project?.name||'')).toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi'));}
function bar(p,c){return `<div class="progress" role="progressbar" aria-label="Tiến độ" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100" style="--color:${c||'var(--orange)'}"><span style="width:${p}%"></span></div>`;}
function go(v,id=null){view=v;active=id;query='';$('#search').value='';render();$('#main').scrollIntoView({block:'start'});$('.sidebar').classList.remove('open');}
function render(){if(view==='projects'&&!project())active=data.projects[0]?.id;const p=project();$('#crumb').textContent={dashboard:'Tổng quan',projects:p?.name||'Bảng dự án',tasks:'Tất cả công việc',timeline:'Timeline',calendar:'Calendar',versions:'Phiên bản'}[view];document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#project-count').textContent=data.projects.length;$('#side-projects').innerHTML=data.projects.map(p=>`<button class="side-project" data-project="${p.id}"><i class="dot" style="background:${p.color}"></i>${esc(p.name)}</button>`).join('');$('#tabs').innerHTML=`<button class="tab tab-home ${view==='dashboard'?'active':''}" role="tab" aria-selected="${view==='dashboard'}" data-view="dashboard" aria-label="Tổng quan">◫</button>`+data.projects.map(p=>`<button role="tab" aria-selected="${active===p.id&&view==='projects'}" class="tab ${active===p.id&&view==='projects'?'active':''}" style="--color:${p.color};--tint:${tint(p.color)}" data-project="${p.id}"><i class="dot" style="background:${p.color}"></i>${esc(p.name)} <span>${progress(p.tasks).pct}%</span></button>`).join('')+`<button class="tab-add" data-action="new-project" aria-label="Thêm tab dự án">+</button>`;$('#main').innerHTML=view==='dashboard'?dashboard():view==='projects'?board():view==='tasks'?tasksPage():view==='timeline'?workTimeline():view==='calendar'?workCalendar():versions();}
function heading(k,title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${k}</span><h1>${title}</h1><p class="subtext">${sub}</p></div>${action}</div>`;}
function dashboard(){const tasks=allTasks(),done=tasks.filter(t=>t.col==='Done').length,doing=tasks.filter(t=>t.col==='Doing').length,pr=progress(tasks);return heading('MỖI NGÀY, MỘT BƯỚC TIẾN','Chào một ngày đầy cảm hứng <span class="orange">✳</span>','Mọi dự án, mọi ý tưởng. Cùng nhau, từng bước thành hình.',`<button class="btn primary" data-action="new-project"><span class="btn-icon">+</span> Tạo dự án</button>`)+`<section class="banner"><div><span class="eyebrow">KHÔNG GIAN CHO NHỮNG ĐIỀU LỚN LAO</span><h2>Ít bộn bề hơn.<br><em>Nhiều điều được hoàn thành hơn.</em></h2><p>Gom ý tưởng vào từng tab. Biến cảm hứng thành hành động.</p></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-sun">✳</div><div class="art-card"></div><div class="art-spark">✧</div></div></section><section class="stats" aria-label="Thống kê công việc">${stat('Tổng dự án',data.projects.length,'Những ý tưởng đang lớn lên','▤')}${stat('Đang thực hiện',doing,'Tập trung vào việc đang làm','◴')}${stat('Đã hoàn thành',done,'Mỗi việc xong, một niềm vui','✓')}${stat('Tiến độ tổng thể',pr.pct+'%','Tính từ task & checklist','↗')}</section><div class="dashboard-grid"><div><div class="section-head"><h2>Các dự án của bạn <span class="orange">.</span></h2><button class="text-btn" data-view="projects">Mở bảng dự án ↗</button></div><div class="project-grid">${data.projects.map(projectCard).join('')||'<div class="empty">Chưa có dự án. Bắt đầu với nút “Tạo dự án”.</div>'}</div><section class="tasks-panel"><div class="section-head"><h2>Nhịp làm việc hôm nay</h2><button class="text-btn" data-view="tasks">Xem tất cả ↗</button></div><div class="panel" style="padding:5px 8px"><div class="table-wrap">${table(tasks.filter(found).filter(t=>['Doing','Done'].includes(t.col)))}</div></div></section></div><aside class="dashboard-right"><section class="panel chart-panel"><h3>Bức tranh công việc</h3><div class="chart-box"><div class="donut" style="--done:${tasks.length?done/tasks.length*100:0}%;--doing:${tasks.length?(done+doing)/tasks.length*100:0}%" role="img" aria-label="${done} hoàn thành, ${doing} đang làm, ${tasks.length-done-doing} chờ thực hiện"><div class="donut-inner"><strong>${tasks.length}</strong><small>Tổng công việc</small></div></div></div><div class="legend"><div><i class="dot" style="background:#7950c8"></i>Đã hoàn thành<strong>${done}</strong></div><div><i class="dot" style="background:#ec84b4"></i>Đang thực hiện<strong>${doing}</strong></div><div><i class="dot" style="background:#e9e3d4"></i>Chờ thực hiện<strong>${tasks.length-done-doing}</strong></div></div><p class="chart-foot">${data.demo?'Dữ liệu minh họa · Có thể xóa trong Hướng dẫn.':'Tổng hợp trực tiếp từ tất cả bảng dự án.'}</p></section><section class="panel version-preview"><div class="version-top"><h3>Chuyện phiên bản</h3><span class="version-tag">v1.1.4</span></div><div class="timeline-item"><small>24 THÁNG 10, 2026</small><h4>First spark · Tia sáng đầu tiên</h4><p>Không gian cho ý tưởng, hành động và những bước tiến nhỏ.</p></div><div class="timeline-item"><h4>Từ tab đến thành quả</h4><p>Tab dự án · Kanban · Checklist · Dashboard</p></div><button class="text-btn" data-view="versions" style="margin-top:16px;padding:0">Khám phá cập nhật →</button></section></aside></div>`;}
function stat(label,note,sub,icon){return `<div class="stat"><span class="stat-label">${label}</span><span class="stat-icon">${icon}</span><div class="stat-value">${note}</div><small>${sub}</small></div>`;}
function projectCard(p){const pr=progress(p.tasks),done=p.tasks.filter(t=>t.col==='Done').length;return `<article class="project-card" tabindex="0" role="button" data-project="${p.id}" style="--color:${p.color};--tint:${tint(p.color)}" aria-label="Mở dự án ${esc(p.name)}"><div class="card-top"><span class="project-icon">${esc(p.icon)}</span><span class="pill">${pr.pct===100&&p.tasks.length?'Hoàn thành':'Đang phát triển'}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="progress-meta"><span>Tiến độ dự án</span><strong>${pr.pct}%</strong></div>${bar(pr.pct,p.color)}<div class="project-bottom"><span>☑ ${done}/${p.tasks.length} công việc</span><span>${p.tasks.filter(t=>t.col==='Doing').length} đang làm ↗</span></div></article>`;}
function table(tasks){return `<table class="task-table"><thead><tr><th>CÔNG VIỆC</th><th>DỰ ÁN</th><th>TRẠNG THÁI</th><th>CHECKLIST</th></tr></thead><tbody>${tasks.map(t=>`<tr data-task="${t.id}" data-pid="${t.project.id}" tabindex="0" role="button" aria-label="Mở ${esc(t.title)}"><td class="task-name">${esc(t.title)}</td><td><i class="dot" style="background:${t.project.color};margin-right:5px"></i>${esc(t.project.name)}</td><td><span class="status ${COLS.includes(t.col)?t.col:''}">${esc(t.col)}</span></td><td><div class="row-progress">${bar(taskPct(t),t.project.color)}<span>${taskPct(t)}%</span></div></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">Chưa có công việc phù hợp.</div></td></tr>'}</tbody></table>`;}
function board(){const p=project();if(!p)return heading('KHỞI ĐẦU MỚI','Mở một tab, gieo một ý tưởng.','Tạo dự án đầu tiên để bắt đầu.',`<button class="btn primary" data-action="new-project">+ Tạo dự án</button>`);const pr=progress(p.tasks);return `<div class="board-head"><div><span class="eyebrow">BẢNG DỰ ÁN / ${esc(p.name).toUpperCase()}</span><h1>${esc(p.icon)} ${esc(p.name)}</h1><p class="subtext">${esc(p.description)}</p></div><div class="board-tools"><button class="btn" data-action="edit-project">⚙ Dự án</button><button class="btn primary" data-action="new-task">+ Thêm công việc</button></div></div><section class="board-summary"><div><strong style="color:${p.color}">${pr.pct}%</strong><p>Tiến độ dự án</p></div><div class="grow"><div class="progress-meta"><span>${pr.done}/${pr.total} đơn vị hoàn thành</span><span>${p.tasks.filter(t=>t.col==='Done').length}/${p.tasks.length} task Done</span></div>${bar(pr.pct,p.color)}<p style="margin-top:6px">Mỗi task + mỗi mục checklist = 1 đơn vị. Kéo thả thẻ hoặc đổi cột trong chi tiết.</p></div></section><div class="board">${p.columns.map((c,i)=>`<section class="column" data-column="${esc(c)}"><div class="column-title"><i class="dot" style="background:${['#bc9977','#c5b57b','#e3a52f','#7c8d64'][i%4]}"></i>${esc(c)}<b>${p.tasks.filter(t=>t.col===c).length}</b><button class="icon-btn" data-action="new-task" data-col="${esc(c)}" aria-label="Thêm task vào ${esc(c)}">+</button></div>${p.tasks.filter(t=>t.col===c&&found(t)).map(t=>taskCard(t,p)).join('')}<button class="add-task" data-action="new-task" data-col="${esc(c)}">+ Thêm công việc</button></section>`).join('')}<button class="add-column" data-action="new-column">+ Thêm cột</button></div>`;}
function taskCard(t,p){const pct=taskPct(t);return `<article class="task-card" draggable="true" data-task="${t.id}" data-pid="${p.id}" role="button" tabindex="0" aria-label="${esc(t.title)}, ${pct}%"><span class="tag">${esc(t.tag||'Công việc')}</span>${labelChips(t)}<h3>${esc(t.title)}</h3>${t.description?`<p>${esc(t.description.slice(0,100))}${t.description.length>100?'…':''}</p>`:''}<div class="progress-meta"><span>☑ ${t.checks.filter(c=>c.done).length}/${t.checks.length} checklist</span><strong>${pct}%</strong></div>${bar(pct,p.color)}<div class="task-footer"><span>${t.due?'◷ '+dateLabel(t.due):'Từng bước tiến lên'}</span><span>${t.due&&t.due<today()&&t.col!=='Done'?'⚑ Quá hạn':'↗'}</span></div></article>`;}
function tasksPage(){const tasks=allTasks().filter(found).filter(t=>(!filterProject||t.project.id===filterProject)&&(!filterStatus||t.col===filterStatus));return heading('MỘT NƠI, MỌI CÔNG VIỆC','Những việc đang thành hình.','Lọc theo dự án và trạng thái để tìm điều cần tập trung.')+`<div class="filter-row"><select id="filter-project" aria-label="Lọc dự án"><option value="">Tất cả dự án</option>${data.projects.map(p=>`<option value="${p.id}" ${filterProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="filter-status" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option>${[...new Set(data.projects.flatMap(p=>p.columns))].map(c=>`<option ${filterStatus===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="panel table-wrap">${table(tasks)}</div>`;}
function versions(){return heading('NHẬT KÝ PHÁT TRIỂN','Phiên bản 1.1.4','Wisdom eye · 24/10/2026')+`<section class="panel release"><div class="timeline-item"><h4>v1.1.4 · Điều hướng tinh gọn</h4><p>Gom Kanban, Timeline, Calendar; icon riêng cho từng chế độ; đưa Phiên bản xuống cuối và tập trung cài đặt vào Settings.</p></div><div class="timeline-item"><h4>v1.1.2 · Niềm vui hoàn thành</h4><p>Pháo hoa, icon và 5 lời chúc ngẫu nhiên khi hoàn thành checklist hoặc task. Checklist cuối cùng chỉ chúc mừng một lần; hỗ trợ giảm chuyển động.</p></div><div class="timeline-item"><h4>v1.1.1 · Con mắt trí tuệ</h4><p>Logo con mắt, bảng màu tím–hồng–cam và nút con mắt hiện/ẩn mật khẩu trong đăng nhập, đăng ký và đặt mật khẩu mới.</p></div><div class="timeline-item"><h4>Tài khoản riêng & dữ liệu</h4><p>Đăng ký email, xác minh, đăng nhập, đặt lại mật khẩu, đăng xuất. Lưu trữ máy chủ theo tài khoản; đồng bộ tự động và phát hiện xung đột. Nhập dữ liệu cũ trên máy sau khi đăng nhập.</p></div><div class="timeline-item"><h4>Các góc nhìn công việc</h4><p>Kanban, Timeline theo ngày đến hạn, Calendar theo tháng. Từ khóa nhiều màu, tìm kiếm và lọc theo dự án.</p></div><div class="timeline-item"><h4>Nhắc việc hằng ngày</h4><p>Email và Web Push lúc 08:00 giờ Việt Nam khi có việc đến hạn hoặc quá hạn. Chủ tài khoản tự bật/tắt trong Settings.</p></div><div class="timeline-item"><h4>Giao diện gọn hơn</h4><p>Loại bỏ ô tên không gian và lời nhắn bên trái theo ảnh đánh dấu. Logo trở về Dashboard, icon nét mảnh và cỡ chữ dễ đọc.</p></div><div class="timeline-item"><h4>v1.0.0 · First spark</h4><p>Tab dự án, Kanban 4 cột, checklist, dashboard tiến độ, sao lưu JSON và giao diện responsive.</p></div></section>`;}

function modal(html,handler,hideSave=false){$('#editor-body').innerHTML=html;$('#editor-form .modal-foot').style.display=hideSave?'none':'';$('#editor-form').onsubmit=e=>{e.preventDefault();handler?.(new FormData(e.target));};if(!$('#editor').open)$('#editor').showModal();}
function field(label,name,value='',type='text',required=false,max=200){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="${max}" ${required?'required':''}></label>`;}
function projectForm(p){if(!p&&data.projects.length>=100)return notify('Tối đa 100 dự án. Hãy xuất bản sao và lưu trữ các dự án cũ.');modal(`<h2>${p?'Chỉnh sửa dự án':'Một dự án mới bắt đầu ✳'}</h2>${field('Tên dự án','name',p?.name||'','text',true,100)}<label class="field">Mô tả<textarea name="description" maxlength="2000">${esc(p?.description||'')}</textarea></label><div class="fields-row">${field('Màu tab dự án','color',p?.color||COLORS[data.projects.length%6],'color')}${field('Biểu tượng (1 ký tự)','icon',p?.icon||'✳','text',true,8)}</div>${p?'<button type="button" class="text-btn danger" data-action="delete-project">Xóa dự án này</button>':''}`,fd=>{const name=fd.get('name').trim();if(!name)return;if(p)Object.assign(p,{name,description:fd.get('description'),color:fd.get('color'),icon:fd.get('icon').trim()||'✳'});else{p={id:uid(),name,description:fd.get('description'),color:fd.get('color'),icon:fd.get('icon').trim()||'✳',columns:[...COLS],tasks:[]};data.projects.push(p);}save();$('#editor').close();go('projects',p.id);notify('Đã lưu dự án. Một ý tưởng đang lớn lên!');});}
function taskForm(p,t,col='List'){if(!t&&p.tasks.length>=2000)return notify('Tối đa 2.000 task mỗi dự án.');editing={p:p.id,t:t?.id};modal(`<h2>${t?'Chỉnh sửa công việc':'Thêm một bước tiến mới'}</h2>${field('Tên công việc','title',t?.title||'','text',true,200)}<label class="field">Mô tả<textarea name="description" maxlength="5000">${esc(t?.description||'')}</textarea></label><div class="fields-row"><label class="field">Cột<select name="col">${p.columns.map(c=>`<option ${c===(t?.col||col)?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Hạn hoàn thành','due',t?.due||'','date')}</div>${field('Nhãn công việc','tag',t?.tag||'','text',false,40)}<label class="field">Từ khóa màu (mỗi dòng: tên | mã màu)<textarea name="labels" maxlength="1500" placeholder="Thiết kế | #d86735&#10;Ưu tiên | #7a8b68">${esc((t?.labels||[]).map(l=>l.name+' | '+l.color).join('\n'))}</textarea></label>${!t?'<label class="field">Checklist (mỗi dòng một mục)<textarea name="checks" maxlength="20000" placeholder="Phác thảo ý tưởng&#10;Hoàn thiện nội dung&#10;Kiểm tra và xuất bản"></textarea></label>':''}`,fd=>{const title=fd.get('title').trim();if(!title)return;const labels=String(fd.get('labels')||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20).map(x=>{const [name,color]=x.split('|');return {name:name.trim().slice(0,40),color:/^#[a-f0-9]{6}$/i.test(color?.trim())?color.trim():COLORS[0]};});const wasDone=t?.col==='Done';const values={labels,title,description:fd.get('description'),col:fd.get('col'),due:fd.get('due'),tag:fd.get('tag')};if(t)Object.assign(t,values);else{t={id:uid(),...values,checks:fd.get('checks').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,200).map(text=>({id:uid(),text:text.slice(0,300),done:false}))};p.tasks.push(t);}if(t.col==='Done')t.checks.forEach(c=>c.done=true);else if(t.checks.length&&t.checks.every(c=>c.done))t.checks.at(-1).done=false;save();render();taskDetail(p,t);if(!wasDone&&t.col==='Done')celebrateCompletion('task');else notify('Đã lưu công việc');});}
function taskDetail(p,t){editing={p:p.id,t:t.id};modal(`<span class="eyebrow">${esc(p.name)} / ${esc(t.col)}</span><h2 style="margin:8px 0 10px;overflow-wrap:anywhere">${esc(t.title)}</h2><div class="detail-actions"><select id="task-state" aria-label="Chuyển cột" class="btn">${p.columns.map(c=>`<option ${t.col===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button type="button" class="btn" data-action="edit-task">✎ Chỉnh sửa</button><button type="button" class="btn danger" data-action="delete-task">Xóa</button></div><p class="detail-description">${esc(t.description||'Chưa có mô tả.')}</p>${labelChips(t)}<div class="progress-meta"><span>${esc(t.tag||'Công việc')} · ${t.due?'Hạn '+dateLabel(t.due):'Chưa đặt hạn'}</span><strong>${taskPct(t)}%</strong></div>${bar(taskPct(t),p.color)}<div class="checklist">${t.checks.map(c=>`<label class="check-row ${c.done?'completed':''}"><input type="checkbox" data-check="${c.id}" ${c.done?'checked':''}><span>${esc(c.text)}</span><button type="button" class="icon-btn" data-remove-check="${c.id}" aria-label="Xóa mục ${esc(c.text)}">×</button></label>`).join('')||'<p class="subtext">Chia nhỏ công việc để bắt đầu dễ hơn.</p>'}</div><div class="check-add"><input id="new-check" maxlength="300" placeholder="Thêm một việc nhỏ…" aria-label="Nội dung checklist mới"><button type="button" class="btn primary" data-action="add-check">+ Thêm</button></div>`,()=>addCheck(),true);}
function selected(){const p=project(editing?.p);return {p,t:p?.tasks.find(t=>t.id===editing?.t)};}
function addCheck(){const {p,t}=selected(),input=$('#new-check'),text=input?.value.trim();if(!t||!text)return;if(t.checks.length>=200)return notify('Tối đa 200 mục checklist mỗi task.');t.checks.push({id:uid(),text,done:false});if(t.col==='Done')t.col='Doing';save();render();taskDetail(p,t);$('#new-check').focus();}
function syncChecks(t){if(t.checks.length&&t.checks.every(c=>c.done))t.col='Done';else if(t.col==='Done')t.col='Doing';}
function moveTask(p,t,col){const wasDone=t.col==='Done';t.col=col;if(col==='Done')t.checks.forEach(c=>c.done=true);else if(t.checks.length&&t.checks.every(c=>c.done))t.checks.at(-1).done=false;save();render();if(!wasDone&&t.col==='Done')celebrateCompletion('task');}
function confirmDelete(kind,fn){modal(`<h2>Xóa ${kind}?</h2><p class="help-copy">Bạn có thể khôi phục lần xóa gần nhất trong Settings. Nên xuất bản sao trước khi xóa dữ liệu quan trọng.</p>`,()=>{undoData=JSON.stringify(data);fn();save();$('#editor').close();render();notify('Đã xóa. Có thể hoàn tác trong Settings.');});}
function help(){modal(`<h2>Hướng dẫn</h2><div class="help-copy"><p>Chọn Kanban, Timeline hoặc Calendar tại nhóm Công việc ở menu bên trái.</p><p>Kanban: thêm task và checklist. Hoàn tất checklist sẽ chuyển task sang Done. Timeline và Calendar hiển thị theo hạn hoàn thành.</p><p>Settings tập trung tài khoản, thông báo, sao lưu JSON, nhập dữ liệu và đồng bộ giữa thiết bị.</p><p>Khi có xung đột, xuất JSON để giữ bản chỉnh sửa rồi chọn dữ liệu máy chủ trong Settings.</p></div>`,null,true);}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-view],[data-project],[data-task],[data-remove-check]');if(!el)return;if(el.dataset.view)return go(el.dataset.view);if(el.dataset.project)return go('projects',el.dataset.project);if(el.dataset.task){const p=project(el.dataset.pid),t=p?.tasks.find(t=>t.id===el.dataset.task);if(t)return taskDetail(p,t);}if(el.dataset.removeCheck){const {p,t}=selected();t.checks=t.checks.filter(c=>c.id!==el.dataset.removeCheck);syncChecks(t);save();render();return taskDetail(p,t);}const p=project();switch(el.dataset.action){case'new-project':return projectForm();case'edit-project':return projectForm(p);case'new-task':return p?taskForm(p,null,el.dataset.col||'List'):projectForm();case'close-modal':return $('#editor').close();case'help':return help();case'edit-task':{const s=selected();return taskForm(s.p,s.t);}case'add-check':return addCheck();case'delete-task':{const s=selected();return confirmDelete('công việc này',()=>{s.p.tasks=s.p.tasks.filter(t=>t.id!==s.t.id);});}case'delete-project':return confirmDelete('dự án và toàn bộ công việc',()=>{data.projects=data.projects.filter(x=>x.id!==p.id);active=null;});case'new-column':return modal(`<h2>Thêm một cột mới</h2>${field('Tên cột','name','','text',true,40)}`,fd=>{const name=fd.get('name').trim();if(!name)return;if(p.columns.includes(name))return notify('Tên cột này đã có.');if(p.columns.length>=20)return notify('Tối đa 20 cột mỗi dự án.');p.columns.push(name);save();render();$('#editor').close();});case'export':{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kanban-zen-studio-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return notify('Đã xuất bản sao dữ liệu JSON.');}case'import':return $('#import-file').click();case'undo':if(undoData){data=JSON.parse(undoData);undoData=null;save();render();$('#editor').close();notify('Đã khôi phục dữ liệu trước lần xóa gần nhất.');}return;case'clear':return confirmDelete('toàn bộ dữ liệu hiện tại',()=>{data={schema:1,demo:false,projects:[]};active=null;});case'demo':data=sample();save();render();$('#editor').close();return notify('Đã nạp dữ liệu minh họa.');}});
document.addEventListener('change',e=>{if(e.target.dataset.check){const {p,t}=selected(),c=t.checks.find(c=>c.id===e.target.dataset.check);const justChecked=!c.done&&e.target.checked,wasDone=t.col==='Done';c.done=e.target.checked;syncChecks(t);save();render();taskDetail(p,t);if(justChecked)celebrateCompletion(!wasDone&&t.col==='Done'?'task':'check');}if(e.target.id==='task-state'){const {p,t}=selected();moveTask(p,t,e.target.value);taskDetail(p,t);}if(e.target.id==='filter-project'){filterProject=e.target.value;render();}if(e.target.id==='filter-status'){filterStatus=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-task],[data-project]')){e.preventDefault();e.target.click();}if(e.key==='Enter'&&e.target.id==='new-check'){e.preventDefault();addCheck();}});
$('#search').addEventListener('input',e=>{query=e.target.value;if(view!=='tasks'&&query){view='tasks';active=null;}render();});
$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');
document.addEventListener('click',e=>{if($('.sidebar').classList.contains('open')&&!e.target.closest('.sidebar')&&!e.target.closest('#menu'))$('.sidebar').classList.remove('open');});
document.addEventListener('dragstart',e=>{const el=e.target.closest('.task-card');if(el){drag={pid:el.dataset.pid,tid:el.dataset.task};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',el.dataset.task);}});
document.addEventListener('dragover',e=>{const c=e.target.closest('.column');if(c&&drag){e.preventDefault();c.classList.add('dragover');e.dataTransfer.dropEffect='move';}});
document.addEventListener('dragleave',e=>{const c=e.target.closest('.column');if(c&&!c.contains(e.relatedTarget))c.classList.remove('dragover');});
document.addEventListener('dragend',()=>{drag=null;document.querySelectorAll('.dragover').forEach(el=>el.classList.remove('dragover'));});
document.addEventListener('drop',e=>{const c=e.target.closest('.column');if(c&&drag){e.preventDefault();const p=project(drag.pid),t=p.tasks.find(t=>t.id===drag.tid);moveTask(p,t,c.dataset.column);drag=null;}});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('File quá lớn (tối đa 5 MB).');const next=JSON.parse(await file.text());if(!valid(next))throw Error('Cấu trúc dữ liệu không hợp lệ hoặc vượt giới hạn.');modal('<h2>Thay dữ liệu bằng bản sao?</h2><p class="help-copy">Bản sao có '+next.projects.length+' dự án. Dữ liệu hiện tại sẽ được thay thế. Hãy xuất bản sao trước nếu cần; có thể hoàn tác lần nhập này trong Settings.</p>',()=>{undoData=JSON.stringify(data);data=next;filterProject='';filterStatus='';save();$('#editor').close();go('dashboard');notify('Đã nhập dữ liệu.');});}catch(err){notify('Không nhập được: '+err.message);}finally{e.target.value='';}};

render();

const iconPaths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',projects:'M3 5h5v14H3z M10 5h5v9h-5z M17 5h4v12h-4z',timeline:'M6 3v18 M3 6h6 M10 5h10v4H10z M10 13h7v4h-7z M3 15h6',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M7 14h2 M13 14h2 M7 18h2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',tasks:'M9 6h11 M9 12h11 M9 18h11 M3 6l1 1 2-3 M3 12l1 1 2-3 M3 18l1 1 2-3',versions:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',check:'M5 12l4 4L19 6',trend:'M4 17l6-6 4 3 6-10 M14 4h6v6'};
function svgIcon(name){return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(iconPaths[name]||iconPaths.clock)+'"/></svg>';}
function refineIcons(){document.querySelectorAll('.nav[data-view]').forEach(el=>{el.querySelector('span').innerHTML=svgIcon(el.dataset.view);});document.querySelectorAll('.stat-icon').forEach((el,i)=>el.innerHTML=svgIcon(['projects','clock','check','trend'][i%4]));const search=document.querySelector('.search>span');if(search)search.innerHTML=svgIcon('search');const home=document.querySelector('.tab-home');if(home)home.innerHTML=svgIcon('dashboard');}
const originalRender=render;render=function(){originalRender();refineIcons();document.querySelectorAll('.view-mode').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.view===view)));const preview=document.querySelector('.version-preview');if(preview){preview.classList.add('version-at-end');$('#main').append(preview);}};refineIcons();

function labelChips(t){return '<div class="label-chips">'+(t.labels||[]).map(l=>{const color=/^#[a-f0-9]{6}$/i.test(l.color)?l.color:'#d86735';return '<button type="button" class="label-chip" data-keyword="'+esc(l.name)+'" style="--label:'+color+'">'+esc(l.name)+'</button>';}).join('')+'</div>';}
let calendarMonth=new Date().getMonth(),calendarYear=new Date().getFullYear();
function dueTasks(){return allTasks().filter(found).filter(t=>!filterProject||t.project.id===filterProject);}
function workFilters(){return '<div class="filter-row"><select id="filter-project" aria-label="Lọc dự án"><option value="">Tất cả dự án</option>'+data.projects.map(p=>'<option value="'+p.id+'" '+(filterProject===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></div>';}
function workTimeline(){const tasks=dueTasks(),dates=[...new Set(tasks.filter(t=>t.due).map(t=>t.due))].sort();return heading('LỊCH CÔNG VIỆC','Timeline','Các mốc hạn hoàn thành theo ngày, từ tất cả dự án.')+workFilters()+'<section class="panel">'+dates.map(d=>'<div class="timeline-item"><h3>'+esc(d.split('-').reverse().join('/'))+'</h3>'+tasks.filter(t=>t.due===d).map(t=>timelineTask(t)).join('')+'</div>').join('')+(tasks.some(t=>!t.due)?'<div class="timeline-item"><h3>Chưa đặt hạn</h3>'+tasks.filter(t=>!t.due).map(timelineTask).join('')+'</div>':'')+(!tasks.length?'<div class="empty">Chưa có công việc.</div>':'')+'</section>';}
function timelineTask(t){return '<button class="calendar-task" data-task="'+t.id+'" data-pid="'+t.project.id+'" style="border-left-color:'+t.project.color+'"><strong>'+esc(t.title)+'</strong><small>'+esc(t.project.name)+' · '+esc(t.col)+' · '+taskPct(t)+'%</small></button>';}
function workCalendar(){const tasks=dueTasks(),first=(new Date(calendarYear,calendarMonth,1).getDay()+6)%7,count=new Date(calendarYear,calendarMonth+1,0).getDate();let cells=Array.from({length:first},()=>'<div class="calendar-day blank"></div>');for(let i=1;i<=count;i++){const d=calendarYear+'-'+String(calendarMonth+1).padStart(2,'0')+'-'+String(i).padStart(2,'0');cells.push('<div class="calendar-day '+(d===today()?'is-today':'')+'"><span>'+i+'</span>'+tasks.filter(t=>t.due===d).map(timelineTask).join('')+'</div>');}return heading('LỊCH CÔNG VIỆC','Calendar','Công việc được sắp theo hạn hoàn thành. Task chưa đặt hạn nằm trong Timeline.')+workFilters()+'<div class="section-head"><button class="btn" data-month="-1" aria-label="Tháng trước">←</button><h2>Tháng '+(calendarMonth+1)+' / '+calendarYear+'</h2><button class="btn" data-month="1" aria-label="Tháng sau">→</button></div><div class="calendar-wrap"><div class="calendar-grid">'+['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','Chủ nhật'].map(d=>'<div class="calendar-weekday">'+d+'</div>').join('')+cells.join('')+'</div></div>';}
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('dashboard');});
const nav=document.querySelector('.sidebar nav');document.querySelector('.view-options').innerHTML=[['projects','Kanban'],['timeline','Timeline'],['calendar','Calendar']].map(([v,label])=>'<button class="view-mode" data-view="'+v+'" aria-pressed="false">'+svgIcon(v)+'<span>'+label+'</span></button>').join('');

document.addEventListener('click',e=>{const kw=e.target.closest('[data-keyword]');if(kw){e.stopPropagation();$('#editor').close();query=kw.dataset.keyword;view='tasks';$('#search').value=query;render();}const month=e.target.closest('[data-month]');if(month){const d=new Date(calendarYear,calendarMonth+Number(month.dataset.month),1);calendarMonth=d.getMonth();calendarYear=d.getFullYear();render();}} ,true);
refineIcons();




const completionMessages=[
 {icon:'spark',text:'Một việc nhỏ hoàn thành, một bước tiến lớn cho hôm nay!'},
 {icon:'trophy',text:'Tuyệt vời! Sự kiên trì của bạn vừa nở thêm một bông hoa.'},
 {icon:'sun',text:'Xong rồi! Hít thở nhẹ nhàng và tận hưởng thành quả nhé.'},
 {icon:'star',text:'Thêm một dấu tích, bớt một nỗi lo. Bạn đang làm rất tốt!'},
 {icon:'rocket',text:'Ý tưởng đã thành hành động, hành động đã thành kết quả. Chúc mừng bạn!'}
];
let completionOverlay=null,completionTimer,lastCompletionMessage=-1;
function dismissCompletion(){clearTimeout(completionTimer);if(completionOverlay){if(completionOverlay.matches(':popover-open'))completionOverlay.hidePopover();completionOverlay.remove();completionOverlay=null;}}
function completionIcon(kind){const paths={spark:'M12 2l2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2Z',trophy:'M8 3h8v6a4 4 0 0 1-8 0V3Z M8 5H4v2a4 4 0 0 0 4 4 M16 5h4v2a4 4 0 0 1-4 4 M12 13v5 M8 21h8 M9 18h6',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1.5 1.5 M17.5 17.5L19 19 M5 19l1.5-1.5 M17.5 6.5L19 5',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3L2.8 9.7l6.4-.9L12 3Z',rocket:'M14 4c3-2 6-2 6-2s0 3-2 6l-7 7-4-4 7-7Z M7 11H3l4-5h5 M11 15v6l5-5v-4 M5 16l-3 6 6-3 M15 6h.01'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[kind]+'"/></svg>';}
function celebrateCompletion(kind='check'){
 dismissCompletion();const choices=completionMessages.map((_,i)=>i).filter(i=>i!==lastCompletionMessage);const index=choices[Math.floor(Math.random()*choices.length)];lastCompletionMessage=index;const message=completionMessages[index];
 const layer=document.createElement('div');layer.className='completion-overlay';layer.setAttribute('popover','manual');
 layer.innerHTML='<div class="completion-fireworks" aria-hidden="true"></div><div class="completion-card" role="status" aria-live="polite"><div class="completion-icon">'+completionIcon(message.icon)+'</div><div><span class="completion-caption">'+(kind==='task'?'HOÀN THÀNH CÔNG VIỆC':'HOÀN THÀNH MỘT BƯỚC')+'</span><p>'+message.text+'</p></div><button type="button" class="completion-close" aria-label="Đóng lời chúc">×</button></div>';
 ($('#editor').open?$('#editor'):document.body).append(layer);completionOverlay=layer;
 if(typeof layer.showPopover==='function')layer.showPopover();else if($('#editor').open)$('#editor').append(layer);
 layer.querySelector('.completion-close').onclick=dismissCompletion;
 if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const colors=['#8c5bd6','#ee83b5','#f2a063','#c4a3ed','#ffc99e'];const particles=layer.querySelector('.completion-fireworks');for(let burst=0;burst<(kind==='task'?5:3);burst++){const x=15+Math.random()*70,y=15+Math.random()*45;for(let i=0;i<18;i++){const a=i/18*Math.PI*2,d=45+Math.random()*(kind==='task'?100:60),p=document.createElement('i');p.className='completion-particle';p.style.cssText='left:'+x+'%;top:'+y+'%;--dx:'+Math.cos(a)*d+'px;--dy:'+Math.sin(a)*d+'px;--delay:'+burst*110+'ms;--particle:'+colors[(i+burst)%colors.length]+';';particles.append(p);}}}
 completionTimer=setTimeout(dismissCompletion,4500);
}
